import{_ as e,o as r,c as o,a2 as l}from"./chunks/framework.CjAa9jTu.js";const m=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/report.md","filePath":"py32f003-getting-started/report.md"}'),i={name:"py32f003-getting-started/report.md"};function n(s,a,t,c,d,p){return r(),o("div",null,[...a[0]||(a[0]=[l(`<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><h2 id="la-compilacion-falla" tabindex="-1">La compilación falla <a class="header-anchor" href="#la-compilacion-falla" aria-label="Permalink to &quot;La compilación falla&quot;">​</a></h2><ul><li>Confirma que el paquete es <strong>UNIT Electronics PY32 0.1.7</strong> y la variante <strong>PY32F003x4</strong>.</li><li>Abre cada <code>.ino</code> en su carpeta independiente; evita varias definiciones de <code>setup()</code> o <code>loop()</code>.</li><li>Lee el primer error de la consola y registra el archivo y la línea indicados.</li><li>Si usas UART, habilita <strong>Enabled (generic &#39;Serial&#39;)</strong> en U(S)ART support.</li><li>Para los ejemplos del taller, utiliza los pines simbólicos PA0, PA1, PA2 y PB5.</li></ul><p>Si aparece un error de desbordamiento de Flash o RAM, revisa el tamaño del programa y sus bibliotecas. No lo resuelvas seleccionando una variante con más memoria que la del microcontrolador instalado.</p><h2 id="pyocd-no-se-encuentra" tabindex="-1">pyOCD no se encuentra <a class="header-anchor" href="#pyocd-no-se-encuentra" aria-label="Permalink to &quot;pyOCD no se encuentra&quot;">​</a></h2><p>Prueba en una terminal:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pyocd --version</span></span>
<span class="line"><span>pyocd list</span></span></code></pre></div><p>Si el primer comando falla, revisa la <a href="./02_0_duino#_2-instalar-pyocd">instalación y el PATH</a>. Reabre Arduino IDE después del cambio. La opción <code>python -m pyocd</code> sólo es adecuada si ese mismo intérprete Python tiene instalado pyOCD; una instalación con pipx se usa mediante el comando <code>pyocd</code> disponible en PATH.</p><h2 id="el-programador-no-aparece" tabindex="-1">El programador no aparece <a class="header-anchor" href="#el-programador-no-aparece" aria-label="Permalink to &quot;El programador no aparece&quot;">​</a></h2><ul><li>Comprueba que el cable USB transmite datos.</li><li>Verifica que el CH552 u otro programador ejecuta firmware CMSIS-DAP.</li><li>Cierra herramientas que puedan mantener abierto el programador.</li><li>En Linux, revisa las <a href="https://pyocd.io/docs/installing.html#udev-rules-on-linux" target="_blank" rel="noreferrer">reglas udev oficiales</a>. El acceso al USB del programador y al puerto serie son permisos diferentes.</li></ul><h2 id="la-carga-falla-aunque-el-programador-aparece" tabindex="-1">La carga falla aunque el programador aparece <a class="header-anchor" href="#la-carga-falla-aunque-el-programador-aparece" aria-label="Permalink to &quot;La carga falla aunque el programador aparece&quot;">​</a></h2><ol><li>Revisa VCC y GND y confirma que la placa está alimentada.</li><li>Revisa SWDIO y SWCLK en ambos extremos del cable.</li><li>Confirma <strong>Upload method → CMSIS-DAP (pyOCD)</strong> y el destino PY32F003x4.</li><li>Desconecta periféricos I²C de las líneas compartidas con la estación apagada.</li><li>Comprueba que existe el archivo <code>Misc/Puya.PY32.pack</code> dentro del paquete instalado.</li><li>Sigue la <a href="./04_swd#recuperacion-basica">recuperación básica por SWD</a>.</li></ol><h2 id="no-aparece-un-puerto-com" tabindex="-1">No aparece un puerto COM <a class="header-anchor" href="#no-aparece-un-puerto-com" aria-label="Permalink to &quot;No aparece un puerto COM&quot;">​</a></h2><p>La programación CMSIS-DAP no necesita un puerto COM. Para usar el monitor serie conecta un adaptador USB-UART de 3.3 V y selecciona <strong>su</strong> puerto. Consulta la <a href="./../examples/lab03-uart">práctica UART</a>.</p><h2 id="el-programa-se-carga-pero-el-led-no-parpadea" tabindex="-1">El programa se carga, pero el LED no parpadea <a class="header-anchor" href="#el-programa-se-carga-pero-el-led-no-parpadea" aria-label="Permalink to &quot;El programa se carga, pero el LED no parpadea&quot;">​</a></h2><ul><li>Comprueba que estás observando el LED de PB5 y que <strong>LED Enable</strong> está cerrado.</li><li>Confirma PB5 como salida y nivel HIGH para encender.</li><li>Pulsa RESET después de la carga.</li><li>En la práctica de validación, comprueba que <code>INYECTAR_FALLA</code> esté en <code>false</code>.</li><li>Carga <a href="./../examples/lab01-blink">01_blink</a> como referencia.</li></ul><h2 id="uart-muestra-caracteres-incorrectos" tabindex="-1">UART muestra caracteres incorrectos <a class="header-anchor" href="#uart-muestra-caracteres-incorrectos" aria-label="Permalink to &quot;UART muestra caracteres incorrectos&quot;">​</a></h2><p>Selecciona 115200 baudios, revisa el reloj HSI de 24 MHz y comprueba TX→RX, RX→TX y GND común. Los mensajes iniciales se pueden perder si el monitor se abre tarde; el ejemplo UART repite un mensaje cada dos segundos.</p><h2 id="adc-no-cambia-o-muestra-valores-inestables" tabindex="-1">ADC no cambia o muestra valores inestables <a class="header-anchor" href="#adc-no-cambia-o-muestra-valores-inestables" aria-label="Permalink to &quot;ADC no cambia o muestra valores inestables&quot;">​</a></h2><p>Revisa el terminal central del potenciómetro en PA2 y sus extremos en 3V3 y GND. Confirma VCC de 3.3 V y <code>analogReadResolution(12)</code>. Retira el pulsador de PA2 y mide la tensión con un multímetro. Una entrada sin conexión queda flotante y no ofrece una lectura de referencia.</p><h2 id="registrar-una-incidencia" tabindex="-1">Registrar una incidencia <a class="header-anchor" href="#registrar-una-incidencia" aria-label="Permalink to &quot;Registrar una incidencia&quot;">​</a></h2><p>Incluye nombre del ejemplo, modelo de la placa, versión del paquete, opciones del menú, primer error completo y pasos para reproducirlo. Adjunta al registro local una fotografía de las conexiones y el resultado esperado. Esa información permite distinguir una falla de montaje de una falla de configuración o código.</p>`,22)])])}const h=e(i,[["render",n]]);export{m as __pageData,h as default};
